/**
 * Stock media for the demo content. Temporary: everything is replaced with the client's
 * own photos and videos before launch. Binaries are downloaded into the seed cache, never committed.
 *
 * Unsplash License: https://unsplash.com/license — free commercial use, no attribution required.
 * Pexels License: https://www.pexels.com/license/ — free commercial use, no attribution required.
 */

export type SeedFile = {
  key: string
  filename: string
  kind: 'image' | 'video' | 'pdf'
  /** Direct download URL; empty for generated files. */
  url: string
  sourcePage: string
  author: string
  license: 'Unsplash License' | 'Pexels License' | 'generated'
  usedIn: string
  alt?: string
  /** Background video: must have no audio track. */
  background?: boolean
  /** Generated placeholder PDF: title printed on the page. */
  pdfTitle?: string
}

const unsplash = (
  key: string,
  name: string,
  id: string,
  width: 600 | 1280 | 1920,
  page: string,
  author: string,
  alt: string,
  usedIn: string,
): SeedFile => ({
  key,
  filename: `mgs-seed-${key.toLowerCase()}-${name}.jpg`,
  kind: 'image',
  url: `https://images.unsplash.com/photo-${id}?w=${width}&q=80&fm=jpg`,
  sourcePage: `https://unsplash.com/photos/${page}`,
  author,
  license: 'Unsplash License',
  usedIn,
  alt,
})

const pexels = (
  key: string,
  name: string,
  id: number,
  variant: string,
  author: string,
  usedIn: string,
  background = false,
): SeedFile => ({
  key,
  filename: `mgs-seed-${key.toLowerCase()}-${name}.mp4`,
  kind: 'video',
  url: `https://videos.pexels.com/video-files/${id}/${id}-${variant}.mp4`,
  sourcePage: `https://www.pexels.com/video/${id}/`,
  author,
  license: 'Pexels License',
  usedIn,
  background,
})

/** Poster frame of a Pexels video (the image Pexels shows for it), 1920 wide. */
const pexelsPhoto = (
  key: string,
  name: string,
  videoId: number,
  author: string,
  alt: string,
  usedIn: string,
): SeedFile => ({
  key,
  filename: `mgs-seed-${key.toLowerCase()}-${name}.jpg`,
  kind: 'image',
  url: `https://images.pexels.com/videos/${videoId}/pexels-photo-${videoId}.jpeg?auto=compress&cs=tinysrgb&w=1920`,
  sourcePage: `https://www.pexels.com/video/${videoId}/`,
  author,
  license: 'Pexels License',
  usedIn,
  alt,
})

